let folded;
/** Folded phrase -> D1 ids, built on first use. */
export function searchKeys() {
  if (!folded) {
    folded = new Map();
    for (const [k, ids] of Object.entries(SEARCH_KEYS)) {
      const f = fold(k);
      folded.set(f, [...new Set([...(folded.get(f) ?? []), ...ids])]);
    }
  }
  return folded;
}
